from fractions import Fraction as Fr
from itertools import combinations
def _inter(s,t):
    (x1,y1),(x2,y2)=s; (x3,y3),(x4,y4)=t
    d=(x2-x1)*(y4-y3)-(y2-y1)*(x4-x3)
    if d==0: return None
    u=((x3-x1)*(y4-y3)-(y3-y1)*(x4-x3))/d; v=((x3-x1)*(y2-y1)-(y3-y1)*(x2-x1))/d
    if 0<=u<=1 and 0<=v<=1: return (x1+u*(x2-x1), y1+u*(y2-y1))
    return None
def _on(p,s):
    (x1,y1),(x2,y2)=s
    if (x2-x1)*(p[1]-y1)-(y2-y1)*(p[0]-x1)!=0: return False
    return min(x1,x2)<=p[0]<=max(x1,x2) and min(y1,y2)<=p[1]<=max(y1,y2)
def _merge(segs):
    segs=[tuple(sorted(s)) for s in segs]
    changed=True
    while changed:
        changed=False
        for s,t in combinations(segs,2):
            if _on(t[0],(s[0],s[1])) or _on(t[1],s) or _on(s[0],t) or _on(s[1],t):
                (x1,y1),(x2,y2)=s
                if all((x2-x1)*(p[1]-y1)-(y2-y1)*(p[0]-x1)==0 for p in t):
                    segs.remove(s); segs.remove(t); segs.append((min(s[0],t[0]),max(s[1],t[1]))); changed=True; break
    return segs
def graph(segs):
    segs=[((Fr(a[0]),Fr(a[1])),(Fr(b[0]),Fr(b[1]))) for a,b in segs]
    segs=_merge(segs)
    P=set()
    for s in segs: P.add(s[0]); P.add(s[1])
    for s,t in combinations(segs,2):
        q=_inter(s,t)
        if q is not None: P.add(q)
    P=sorted(P)
    on=[frozenset(i for i,p in enumerate(P) if _on(p,s)) for s in segs]
    conn=lambda i,j: any(i in o and j in o for o in on)
    col=lambda i,j,k: (P[j][0]-P[i][0])*(P[k][1]-P[i][1])-(P[j][1]-P[i][1])*(P[k][0]-P[i][0])==0
    return P,conn,col
def triangles(segs):
    P,conn,col=graph(segs)
    return sum(1 for i,j,k in combinations(range(len(P)),3) if conn(i,j) and conn(j,k) and conn(i,k) and not col(i,j,k))
def rects(segs, squares_only=False):
    P,conn,col=graph(segs); idx={p:i for i,p in enumerate(P)}; found=set()
    for q in range(len(P)):
        for p in range(len(P)):
            for r in range(len(P)):
                if len({p,q,r})<3 or not (conn(p,q) and conn(q,r)): continue
                a=(P[p][0]-P[q][0],P[p][1]-P[q][1]); b=(P[r][0]-P[q][0],P[r][1]-P[q][1])
                if a[0]*b[0]+a[1]*b[1]!=0: continue
                if squares_only and a[0]**2+a[1]**2!=b[0]**2+b[1]**2: continue
                s=(P[p][0]+b[0],P[p][1]+b[1])
                if s in idx and conn(idx[s],p) and conn(idx[s],r): found.add(frozenset((p,q,r,idx[s])))
    return len(found)
segs=[((0, 0), (12, 0)), ((0, 0), (6, 8)), ((12, 0), (6, 8)), ((6, 8), (3, 0)), ((6, 8), (6, 0)), ((6, 8), (9, 0)), ((3, 4), (9, 4))]
ans=triangles(segs)

